package com._8x8.herd.device_logs.processor.index.dynamodb;

import com._8x8.herd.device_logs.processor.index.IndexRow;
import com._8x8.herd.device_logs.processor.index.IndexStore;
import com._8x8.herd.device_logs.processor.index.IndexStoreException;
import com._8x8.herd.device_logs.processor.index.WriteResult;

import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

import software.amazon.awssdk.core.exception.SdkException;
import software.amazon.awssdk.services.dynamodb.DynamoDbClient;
import software.amazon.awssdk.services.dynamodb.model.AttributeValue;
import software.amazon.awssdk.services.dynamodb.model.ConditionalCheckFailedException;

/**
 * Writes each row with one conditional PutItem. It never reads the existing row, which the role does not allow and the
 * first-write-wins rule does not need.
 */
public class DynamoDbIndexStore implements IndexStore {

    // Always three digits of milliseconds, unlike Instant.toString(), so the sort keys order by time.
    private static final DateTimeFormatter TIMESTAMP = DateTimeFormatter.ofPattern("uuuu-MM-dd'T'HH:mm:ss.SSS'Z'")
            .withZone(ZoneOffset.UTC);

    private final DynamoDbClient dynamoDb;
    private final String table;

    public DynamoDbIndexStore(DynamoDbClient dynamoDb, String table) {
        this.dynamoDb = dynamoDb;
        this.table = table;
    }

    @Override
    public WriteResult write(IndexRow row) {
        try {
            dynamoDb.putItem(request -> request.tableName(table).item(item(row)).conditionExpression("attribute_not_exists(mac)"));
            return WriteResult.CREATED;
        } catch (ConditionalCheckFailedException e) {
            return WriteResult.ALREADY_EXISTS;
        } catch (SdkException e) {
            throw new IndexStoreException(row.key(), e);
        }
    }

    private static Map<String, AttributeValue> item(IndexRow row) {
        String receivedAt = timestamp(row.receivedAt());
        Map<String, AttributeValue> item = new HashMap<>();
        item.put("mac", AttributeValue.fromS(row.mac().lowercase()));
        item.put("received_at_type", AttributeValue.fromS(receivedAt + "#" + row.type().suffix()));
        item.put("received_at", AttributeValue.fromS(receivedAt));
        item.put("key", AttributeValue.fromS(row.key()));
        item.put("size_bytes", AttributeValue.fromN(Long.toString(row.sizeBytes())));
        item.put("etag", AttributeValue.fromS(row.etag()));
        putIfPresent(item, "source_ip", row.sourceIp());
        putIfPresent(item, "cert_serial", row.certSerial());
        item.put("manual", AttributeValue.fromBool(row.manual()));
        putIfPresent(item, "original_name", row.originalName());
        putIfPresent(item, "model", row.model());
        putIfPresent(item, "firmware", row.firmware());
        putIfPresent(item, "boot_stage", row.bootStage());
        item.put("customer_id", AttributeValue.fromS(row.customerId()));
        // DynamoDB TTL only acts on a Number of epoch seconds.
        item.put("ttl", AttributeValue.fromN(Long.toString(row.ttl().getEpochSecond())));
        item.put("indexed_at", AttributeValue.fromS(timestamp(row.indexedAt())));
        return item;
    }

    // Left out rather than written empty, so a query can test whether the phone sent the field.
    private static void putIfPresent(Map<String, AttributeValue> item, String name, Optional<String> value) {
        value.ifPresent(present -> item.put(name, AttributeValue.fromS(present)));
    }

    private static String timestamp(Instant instant) {
        return TIMESTAMP.format(instant);
    }
}

