import com._8x8.herd.device_logs.processor.storage.ObjectMetadata;
import com._8x8.herd.device_logs.processor.storage.ObjectMetadataException;
import com._8x8.herd.device_logs.processor.storage.ObjectMetadataReader;
import com._8x8.herd.device_logs.processor.useragent.PolyUserAgent;

import java.time.Clock;
import java.time.Duration;
import java.time.temporal.ChronoUnit;
import java.util.Optional;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Indexes one uploaded object: parses its key, reads its metadata, looks up its customer and writes its row, stopping
 * at the first failure. Expected failures come back as an outcome, never as an exception.
 */
public class RecordIndexer {

    private static final Logger LOG = LoggerFactory.getLogger(RecordIndexer.class);
    private static final String UNASSIGNED = "unassigned";

    private final ObjectMetadataReader metadataReader;
    private final CustomerLookup customerLookup;
    private final IndexStore store;
    private final Clock clock;
    private final Duration retention;

    public RecordIndexer(ObjectMetadataReader metadataReader, CustomerLookup customerLookup, IndexStore store,
                         Clock clock, Duration retention) {
        this.metadataReader = metadataReader;
        this.customerLookup = customerLookup;
        this.store = store;
        this.clock = clock;
        this.retention = retention;
    }

    public IndexingOutcome index(UploadedObject object) {
        Optional<ObjectKey> parsed = ObjectKey.parse(object.key());
        if (parsed.isEmpty()) {
            LOG.warn("Not indexed {}: {}", object.key(), IndexingOutcome.UNPARSEABLE_KEY);
            return IndexingOutcome.UNPARSEABLE_KEY;
        }
        ObjectKey key = parsed.get();

        ObjectMetadata metadata;
        try {
            metadata = metadataReader.read(object.key());
        } catch (ObjectMetadataException e) {
            return failed(object, IndexingOutcome.METADATA_UNREADABLE, e);
        }

        String customerId;
        try {
            // No customer is an unknown MAC, which is still indexed (ADR 0020).
            customerId = customerLookup.customerOf(key.mac()).orElse(UNASSIGNED);
        } catch (CustomerLookupException e) {
            return failed(object, IndexingOutcome.LOOKUP_FAILED, e);
        }

        // Parsed after the lookup, so a record that keeps failing there doesn't warn about its user agent on each retry.
        Optional<PolyUserAgent> userAgent = metadata.userAgent().flatMap(PolyUserAgent::parse);
        if (metadata.userAgent().isPresent() && userAgent.isEmpty()) {
            LOG.warn("User agent of {} does not parse, indexing it without model, firmware and boot stage", object.key());
        }
        IndexRow row = new IndexRow(key.mac(), key.receivedAt(), key.type(), object.key(), object.sizeBytes(), object.etag(), metadata.sourceIp(), metadata.certSerial(), metadata.manual(), metadata.originalName(), userAgent.map(PolyUserAgent::model), userAgent.map(PolyUserAgent::firmware), userAgent.flatMap(PolyUserAgent::bootStage), customerId, key.receivedAt().plus(retention), clock.instant().truncatedTo(ChronoUnit.MILLIS));
        try {
            return store.write(row) == WriteResult.CREATED ? IndexingOutcome.INDEXED : IndexingOutcome.ALREADY_INDEXED;
        } catch (IndexStoreException e) {
            return failed(object, IndexingOutcome.WRITE_FAILED, e);
        }
    }

    private static IndexingOutcome failed(UploadedObject object, IndexingOutcome outcome, RuntimeException cause) {
        LOG.warn("Not indexed {}: {}", object.key(), outcome, cause);
        return outcome;
    }
}

